111	    @Transactional
112	    public void updateSaleStatusToSold(Long orderId) {
113	        log.info("판매 상태를 'SOLD'로 변경 시작: orderId={}", orderId);
114	
115	
116	        StyleBid saleBid = saleBidQueryService.findByOrderId(orderId);
117	        if (saleBid != null) {
118	            Style sale = saleBid.getSale();
119	            if (sale != null && sale.getStatus().canTransitionTo(StyleStatus.SOLD)) {
120	                log.info("Style 상태 'SOLD'로 변경: saleId={}, sellerId={}",
121	                        sale.getId(), sale.getSeller().getId());
122	
123	                sale.updateStatus(StyleStatus.SOLD);
124	
125	
126	                if (sale.isWarehouseStorage()) {
127	                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
128	                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
129	                }
130	
131	
132	                Product seller = sale.getSeller();
133	                notificationCommandService.createNotification(
134	                        seller.getId(),
135	                        PaymentCategory.SHOPPING,
136	                        PaymentType.BID,
137	                        "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
138	                );
139	
140	                log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
141	                        seller.getId(), sale.getId());
142	            } else {
143	                log.debug("Style 상태 변경 불가 또는 Sale이 null: saleBidId={}", saleBid.getId());
144	            }
145	        } else {
146	            log.debug("해당 주문과 연결된 SaleBid가 없음: orderId={}", orderId);
147	        }
148	
149	
150	        try {
151	            FaqBid orderBid = orderBidQueryService.findByOrderId(orderId)
152	                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));
153	
154	            if (orderBid != null) {
155	                Style sale = orderBid.getSale();
156	                if (sale != null && sale.getStatus().canTransitionTo(StyleStatus.SOLD)) {
157	                    log.info("FaqBid 기반 Style 상태 'SOLD'로 변경: orderBidId={}, saleId={}",
158	                            orderBid.getId(), sale.getId());
159	
160	                    sale.updateStatus(StyleStatus.SOLD);
161	
162	
163	                    Product seller = sale.getSeller();
164	                    notificationCommandService.createNotification(
165	                            seller.getId(),
166	                            PaymentCategory.SHOPPING,
167	                            PaymentType.BID,
168	                            "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
169	                    );
170	
171	                    log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
172	                            seller.getId(), sale.getId());
173	                } else {
174	                    log.debug("Style 상태 변경 불가 또는 Sale이 null: orderBidId={}", orderBid.getId());
175	                }
176	            }
177	        } catch (IllegalArgumentException e) {
178	            log.warn("FaqBid 조회 실패: orderId={}, error={}", orderId, e.getMessage());
179	
180	        }
181	
182	        log.info("판매 상태 'SOLD' 변경 작업 완료: orderId={}", orderId);
183	    }
