   402	    @Bean
   403	    @StepScope
   404	    public ItemProcessor<FaqAddress, FaqAddress> shipmentItemProcessor() {
   405	        log.debug("배송 상태 업데이트 ItemProcessor 구성");
   406	
   407	
   408	        return orderShipment -> {
   409	            String trackingNumber = orderShipment.getTrackingNumber();
   410	            Long shipmentId = orderShipment.getId();
   411	
   412	            if (trackingNumber == null || trackingNumber.isBlank()) {
   413	                log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
   414	                throw new AddressException(AddressErrorCode.TRACKING_NUMBER_INVALID);
   415	            }
   416	
   417	            log.info("배송 상태 조회 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
   418	                    shipmentId, trackingNumber, orderShipment.getStatus());
   419	
   420	            try {
   421	
   422	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
   423	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}", shipmentId, currentStatus);
   424	
   425	
   426	                AddressStatus newStatus = mapToShipmentStatus(currentStatus);
   427	                log.debug("배송 상태 매핑 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
   428	
   429	
   430	                if (orderShipment.getStatus() == newStatus) {
   431	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
   432	                            shipmentId, newStatus);
   433	                    return orderShipment;
   434	                }
   435	
   436	
   437	                if (newStatus == AddressStatus.DELIVERED) {
   438	                    log.info("배송 완료 처리: shipmentId={}, orderId={}",
   439	                            shipmentId, orderShipment.getOrder().getId());
   440	
   441	                    orderShipment.updateStatus(AddressStatus.DELIVERED);
   442	
   443	                    orderService.completeOrder(orderShipment.getOrder().getId());
   444	
   445	                    notificationService.notifyShipmentCompleted(orderShipment.getOrder());
   446	                }
   447	                else if (newStatus == AddressStatus.OUT_FOR_DELIVERY) {
   448	                    log.info("배송 출발 처리: shipmentId={}", shipmentId);
   449	                    orderShipment.updateStatus(AddressStatus.OUT_FOR_DELIVERY);
   450	
   451	                }
   452	                else {
   453	                    log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
   454	                    orderShipment.updateStatus(AddressStatus.IN_TRANSIT);
   455	                }
   456	
   457	                log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}", shipmentId, orderShipment.getStatus());
   458	                return orderShipment;
   459	
   460	            } catch (Exception e) {
   461	                log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
   462	                        shipmentId, trackingNumber, e.getMessage(), e);
   463	
   464	
   465	                if (!(e instanceof AddressException)) {
   466	                    throw new AddressException(
   467	                            AddressErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
   468	                            "배송 상태 조회 중 오류 발생: " + e.getMessage(),
   469	                            e
   470	                    );
   471	                }
   472	                throw e;
   473	            }
   474	        };
   475	    }
