   484	    private String parseCjLogisticsStatus(String trackingNumber) throws Exception {
   485	        log.debug("운송장 조회 시작 (Jsoup): trackingNumber={}", trackingNumber);
   486	
   487	        try {
   488	
   489	            String url = "https://trace.cjlogistics.com/next/tracking.html?wblNo=" + trackingNumber;
   490	            Document doc = Jsoup.connect(url).get();
   491	
   492	            Elements rows = doc.select("tbody#statusDetail tr");
   493	            if (rows.isEmpty()) {
   494	                log.warn("배송 정보가 없음: trackingNumber={}", trackingNumber);
   495	                throw new AddressException(
   496	                        AddressErrorCode.TRACKING_HTML_PARSE_ERROR,
   497	                        "배송 정보가 없습니다. trackingNo=" + trackingNumber
   498	                );
   499	            }
   500	
   501	            String status = rows.last().select("td").get(4).text();
   502	            log.debug("운송장 조회 완료: trackingNumber={}, status={}", trackingNumber, status);
   503	            return status;
   504	
   505	        } catch (Exception e) {
   506	            log.error("운송장 조회 실패: trackingNumber={}, error={}", trackingNumber, e.getMessage(), e);
   507	
   508	            if (e instanceof AddressException) {
   509	                throw e;
   510	            }
   511	
   512	            throw new AddressException(
