 14	        }
 15	    },
 16	    IN_TRANSIT {
 17	        @Override
 18	        public boolean canTransitionTo(AddressStatus nextStatus) {
 19	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
 20	                    || nextStatus == DELIVERED;
 21	        }
 22	    },
 23	    OUT_FOR_DELIVERY {
 24	        @Override
