125	public enum FaqStatus {
126	    PENDING_PAYMENT,
127	    PAYMENT_COMPLETED,
128	    PREPARING,
129	    IN_WAREHOUSE,
130	    SHIPMENT_STARTED,
131	    IN_TRANSIT,
132	    COMPLETED,
133	    REFUND_REQUESTED,
134	    REFUNDED;
137	    private static final Map<FaqStatus, Set<FaqStatus>> ALLOWED_TRANSITIONS = new HashMap<>();
139	    static {
141	        ALLOWED_TRANSITIONS.put(PENDING_PAYMENT, Set.of(PAYMENT_COMPLETED, COMPLETED, IN_WAREHOUSE));
142	        ALLOWED_TRANSITIONS.put(PAYMENT_COMPLETED, Set.of(PREPARING, REFUND_REQUESTED, IN_WAREHOUSE));
143	        ALLOWED_TRANSITIONS.put(PREPARING, Set.of(IN_WAREHOUSE, SHIPMENT_STARTED));
144	        ALLOWED_TRANSITIONS.put(IN_WAREHOUSE, Set.of(SHIPMENT_STARTED, COMPLETED));
145	        ALLOWED_TRANSITIONS.put(SHIPMENT_STARTED, Set.of(IN_TRANSIT));
146	        ALLOWED_TRANSITIONS.put(IN_TRANSIT, Set.of(COMPLETED));
147	        ALLOWED_TRANSITIONS.put(REFUND_REQUESTED, Set.of(REFUNDED));
148	        ALLOWED_TRANSITIONS.put(COMPLETED, Collections.emptySet());
149	        ALLOWED_TRANSITIONS.put(REFUNDED, Collections.emptySet());
150	    }
158	    public boolean canTransitionTo(FaqStatus newStatus) {
159	        Set<FaqStatus> allowedNextStates = ALLOWED_TRANSITIONS.get(this);
160	        return allowedNextStates != null && allowedNextStates.contains(newStatus);
161	    }
168	    public Set<FaqStatus> getAllowedNextStates() {
169	        return Collections.unmodifiableSet(ALLOWED_TRANSITIONS.getOrDefault(this, Collections.emptySet()));
170	    }
